import { SenderChainKey } from './sender-chain-key'
import { SenderMessageKey } from './sender-message-key'

interface SenderChainKeyStructure {
	iteration: number
	seed: Uint8Array
}

interface SenderSigningKeyStructure {
	public: Uint8Array
	private?: Uint8Array
}

interface SenderMessageKeyStructure {
	iteration: number
	seed: Uint8Array
}

interface SenderKeyStateStructure {
	senderKeyId: number
	senderChainKey: SenderChainKeyStructure
	senderSigningKey: SenderSigningKeyStructure
	senderMessageKeys: SenderMessageKeyStructure[]
}

/**
 * SenderKeyState - Estado individual de uma chave de remetente
 * Implementação robusta com validação defensiva de tipos
 */
export class SenderKeyState {
	private readonly MAX_MESSAGE_KEYS = 2000
	private readonly senderKeyStateStructure: SenderKeyStateStructure

	constructor(
		id?: number | null,
		iteration?: number | null,
		chainKey?: Uint8Array | null | string,
		signatureKeyPair?: { public: Uint8Array | string; private: Uint8Array | string } | null,
		signatureKeyPublic?: Uint8Array | string | null,
		signatureKeyPrivate?: Uint8Array | string | null,
		senderKeyStateStructure?: SenderKeyStateStructure | unknown | null
	) {
		if (senderKeyStateStructure) {
			if (!this.isValidStructure(senderKeyStateStructure)) {
				this.senderKeyStateStructure = this.createDefaultStructure(id, iteration, chainKey, signatureKeyPublic, signatureKeyPrivate)
				return
			}

			try {
				const struct = senderKeyStateStructure as SenderKeyStateStructure
				this.senderKeyStateStructure = {
					senderKeyId: this.validateNumber(struct.senderKeyId, 0),
					senderChainKey: this.validateChainKey(struct.senderChainKey),
					senderSigningKey: this.validateSigningKey(struct.senderSigningKey),
					senderMessageKeys: this.validateMessageKeys(struct.senderMessageKeys)
				}
			} catch {
				this.senderKeyStateStructure = this.createDefaultStructure(id, iteration, chainKey, signatureKeyPublic, signatureKeyPrivate)
			}
		} else {
			if (signatureKeyPair) {
				signatureKeyPublic = signatureKeyPair.public
				signatureKeyPrivate = signatureKeyPair.private
			}
			this.senderKeyStateStructure = this.createDefaultStructure(id, iteration, chainKey, signatureKeyPublic, signatureKeyPrivate)
		}
	}

	/**
	 * Valida se a estrutura é um objeto válido (não primitivo)
	 */
	private isValidStructure(structure: unknown): structure is SenderKeyStateStructure {
		// Rejeitar tipos primitivos
		if (typeof structure !== 'object' || structure === null) {
			return false
		}
		return true
	}

	/**
	 * Cria uma estrutura padrão válida
	 */
	private createDefaultStructure(
		id?: number | null,
		iteration?: number | null,
		chainKey?: Uint8Array | null | string,
		signatureKeyPublic?: Uint8Array | string | null,
		signatureKeyPrivate?: Uint8Array | string | null
	): SenderKeyStateStructure {
		return {
			senderKeyId: this.validateNumber(id, 0),
			senderChainKey: {
				iteration: this.validateNumber(iteration, 0),
				seed: this.toBuffer(chainKey)
			},
			senderSigningKey: {
				public: this.toBuffer(signatureKeyPublic),
				private: this.toBuffer(signatureKeyPrivate)
			},
			senderMessageKeys: []
		}
	}

	/**
	 * Valida e retorna um número
	 */
	private validateNumber(value: unknown, defaultValue: number): number {
		if (typeof value === 'number' && !isNaN(value)) {
			return value
		}
		if (typeof value === 'string') {
			const parsed = parseInt(value, 10)
			if (!isNaN(parsed)) return parsed
		}
		return defaultValue
	}

	/**
	 * Converte valor para Buffer de forma segura
	 * Trata casos especiais de deserialização JSON onde Uint8Array vira objeto
	 */
	private toBuffer(value: Uint8Array | string | null | undefined | Record<string, unknown>): Buffer {
		if (!value) return Buffer.from([])
		if (Buffer.isBuffer(value)) return value
		if (value instanceof Uint8Array) return Buffer.from(value)
		if (Array.isArray(value)) return Buffer.from(value)
		if (typeof value === 'string') return Buffer.from(value, 'base64')
		
		// Tratar objeto que parece array (resultado de JSON.parse de Uint8Array)
		// Formato: { type: 'Buffer', data: [...] } ou { 0: x, 1: y, ... }
		if (typeof value === 'object') {
			// Formato BufferJSON: { type: 'Buffer', data: [...] }
			if ('type' in value && value.type === 'Buffer' && 'data' in value && Array.isArray(value.data)) {
				return Buffer.from(value.data as number[])
			}
			
			// Formato objeto com índices numéricos: { 0: x, 1: y, 2: z, ... }
			const keys = Object.keys(value)
			if (keys.length > 0 && keys.every(k => !isNaN(parseInt(k, 10)))) {
				const arr: number[] = []
				for (const k of keys.sort((a, b) => parseInt(a) - parseInt(b))) {
					arr.push(value[k] as number)
				}
				return Buffer.from(arr)
			}
		}
		
		return Buffer.from([])
	}

	/**
	 * Valida a estrutura de chainKey
	 */
	private validateChainKey(chainKey: unknown): SenderChainKeyStructure {
		if (!chainKey || typeof chainKey !== 'object') {
			return { iteration: 0, seed: Buffer.from([]) }
		}
		const ck = chainKey as SenderChainKeyStructure
		return {
			iteration: this.validateNumber(ck.iteration, 0),
			seed: this.toBuffer(ck.seed as Uint8Array)
		}
	}

	/**
	 * Valida a estrutura de signingKey
	 */
	private validateSigningKey(signingKey: unknown): SenderSigningKeyStructure {
		if (!signingKey || typeof signingKey !== 'object') {
			return { public: Buffer.from([]), private: Buffer.from([]) }
		}
		const sk = signingKey as SenderSigningKeyStructure
		return {
			public: this.toBuffer(sk.public as Uint8Array),
			private: this.toBuffer(sk.private as Uint8Array)
		}
	}

	/**
	 * Valida e limpa o array de messageKeys
	 */
	private validateMessageKeys(messageKeys: unknown): SenderMessageKeyStructure[] {
		if (!Array.isArray(messageKeys)) {
			return []
		}

		// Filtrar apenas entradas válidas
		return messageKeys
			.filter((key: unknown) => {
				if (!key || typeof key !== 'object') return false
				const k = key as Record<string, unknown>
				return typeof k.iteration === 'number' || 'seed' in k
			})
			.slice(0, this.MAX_MESSAGE_KEYS) as SenderMessageKeyStructure[]
	}

	public getKeyId(): number {
		return this.senderKeyStateStructure.senderKeyId
	}

	public getSenderChainKey(): SenderChainKey {
		return new SenderChainKey(
			this.senderKeyStateStructure.senderChainKey.iteration,
			this.senderKeyStateStructure.senderChainKey.seed
		)
	}

	public setSenderChainKey(chainKey: SenderChainKey): void {
		this.senderKeyStateStructure.senderChainKey = {
			iteration: chainKey.getIteration(),
			seed: chainKey.getSeed()
		}
	}

	public getSigningKeyPublic(): Buffer {
		const publicKey = Buffer.from(this.senderKeyStateStructure.senderSigningKey.public)

		// Validar se a chave pública tem tamanho válido
		if (publicKey.length === 0) {
			throw new Error('Invalid public key: empty key')
		}

		// Chave de 32 bytes precisa do prefixo 0x05
		if (publicKey.length === 32) {
			const fixed = Buffer.alloc(33)
			fixed[0] = 0x05
			publicKey.copy(fixed, 1)
			return fixed
		}

		// Chave de 33 bytes já tem o prefixo
		if (publicKey.length === 33) {
			// Validar que o primeiro byte é 0x05 (prefixo curve25519)
			if (publicKey[0] !== 0x05) {
				throw new Error('Invalid public key: wrong prefix')
			}
			return publicKey
		}

		// Tamanho inválido
		throw new Error(`Invalid public key: wrong length (${publicKey.length})`)
	}

	public getSigningKeyPrivate(): Buffer | undefined {
		const privateKey = this.senderKeyStateStructure.senderSigningKey.private

		return Buffer.from(privateKey || [])
	}

	public hasSenderMessageKey(iteration: number): boolean {
		return this.senderKeyStateStructure.senderMessageKeys.some(key => key.iteration === iteration)
	}

	public addSenderMessageKey(senderMessageKey: SenderMessageKey): void {
		this.senderKeyStateStructure.senderMessageKeys.push({
			iteration: senderMessageKey.getIteration(),
			seed: senderMessageKey.getSeed()
		})

		if (this.senderKeyStateStructure.senderMessageKeys.length > this.MAX_MESSAGE_KEYS) {
			this.senderKeyStateStructure.senderMessageKeys.shift()
		}
	}

	public removeSenderMessageKey(iteration: number): SenderMessageKey | null {
		const index = this.senderKeyStateStructure.senderMessageKeys.findIndex(key => key.iteration === iteration)

		if (index !== -1) {
			const messageKey = this.senderKeyStateStructure.senderMessageKeys[index]!
			this.senderKeyStateStructure.senderMessageKeys.splice(index, 1)
			return new SenderMessageKey(messageKey.iteration, messageKey.seed)
		}

		return null
	}

	public getStructure(): SenderKeyStateStructure {
		return this.senderKeyStateStructure
	}
}
